  function points(id, n = 22) {
    const art = ART[id];
    if (id === 'trump') {
      const keep = n >= 30 ? TRUMP.length : Math.min(TRUMP.length, 220 + n * 8);
      const step = Math.max(1, Math.ceil(TRUMP.length / keep));
      const out = [];
      for (let i = 0; i < TRUMP.length; i += step) out.push(TRUMP[i]);
      return out;
    }
    if (!art) return [];
    n = Math.max(10, Math.min(40, n | 0));
    const out = [], step = 2 / n;
    for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
      const x = -1 + (i + 0.5) * step, y = -1 + (j + 0.5) * step;
      let col;
      for (const op of art) if (covers(op, x, y)) col = colourOf(op);
      if (col) out.push([x + (Math.random() - 0.5) * step * 0.35, y + (Math.random() - 0.5) * step * 0.35, col]);
    }
    return out;
  }
