  const dancer = (la, ra, ll, rl) => [circle(0, -0.72, 0.13), [[0, -0.58], [0, 0.06]], [[-0.02, 0.06], [-0.42, 0.42], [0.42, 0.42], [0.02, 0.06]], [[-0.1, -0.48], ...la], [[0.1, -0.48], ...ra], [[-0.1, 0.36], ...ll], [[0.1, 0.36], ...rl]];
